  "items:scavenger_boots:name": "Сапоги падальщика",
  "items:sevenfold_crown_chain:description": "Семь сломанных корон свисают с одной цепи — по одной на каждого из Безмолвных. Носилась на груди самого Некоронованного, пока он не решил путешествовать налегке.",
  "items:sevenfold_crown_chain:name": "Цепь Семи Сломанных Корон",
  "items:shade_rune:name": "Руна тени",
  "items:shade_wisp:description": "Пойманный обрывок призрачной энергии воющей тени. Мерцает скорбным светом. Заготовка рунотворчества.",
  "items:shade_wisp:name": "Огонёк тени",
  "items:shadestalker_hood:name": "Капюшон теневого охотника",
  "items:shadowhide:description": "Тронутая пустотой шкура, что словно поглощает свет. Редка сверх всякой меры.",
  "items:shadowhide:name": "Теневая шкура",
