  "items:sickle_shiv:name": "Заточка-серп",
  "items:signet_ring:name": "Кольцо-печатка",
  "items:silk_mantle:description": "Лёгкий плащ, сотканный из шёлка ямного паука. Любим равно следопытами и ведунами.",
  "items:silk_mantle:name": "Шёлковая мантия",
  "items:siren_shockstaff:name": "Разрядный посох сирены",
  "items:skarn_idol_staff:description": "Посох, вытесанный из окристаллизованного хребта Драконошкурого Скарна. Горит без топлива.",
  "items:skarn_idol_staff:name": "Посох идола Скарна",
  "items:skeletal_longbow:name": "Костяной длинный лук",
  "items:skybreaker_greatsword:name": "Двуручный меч «Небокрушитель»",
  "items:skygrip_gauntlets:name": "Латные рукавицы небесной хватки",
  "items:skytalon_recurve:name": "Лук «Небесный коготь»",
  "items:slag_carapace:description": "Закалённый, сплавленный с лавой хитин шлаковой мерзости. Кузнечный материал для деталей башенной брони.",
  "items:slag_carapace:name": "Шлаковый панцирь",
  "items:slagcarapace_plate:name": "Латы из шлакового панциря",
  "items:slagforged_sword:name": "Меч шлаковой ковки",
  "items:slagheart_cuirass:name": "Кираса шлакового сердца",
  "items:slagweave_cape:name": "Плащ шлакового плетения",
  "items:slayer_amulet:description": "Кристаллический амулет с осколком вестника пустоты. Излучает холодную, точную мощь во всех стилях боя.",
  "items:slayer_amulet:name": "Амулет истребителя",
  "items:slayer_combat_draught:description": "Дистиллят из эссенции Башни Истребителя. Ускоряет удары (-450 мс к интервалу атаки) и обостряет прицел (+8% крит) на 10 минут.",
  "items:slayer_combat_draught:name": "Боевой отвар истребителя",
  "items:slayer_greaves:description": "Поножи, укреплённые расколотыми осколками зубов жуткого клыка. Созданы для добычи не твоего ранга: +20% урона по монстрам, чей боевой уровень выше твоего.",
  "items:slayer_greaves:name": "Поножи истребителя",
  "items:slayer_helm:description": "Шедевральный шлем, выкованный из эссенции худших ужасов Башни Истребителя. Он отмечает поручение своего носителя: +20% урона по текущей цели задания, а предметы-обереги против любых угроз башни больше не нужны, пока он надет.",
  "items:slayer_helm:name": "Шлем истребителя",
  "items:slayer_hunters_cape:description": "Потрёпанный плащ, который Бренна выдаёт охотникам, заслужившим свои первые тридцать контрактов. Первый удар каждой охоты бьёт сильнее всего: +15% урона по ещё неповреждённой цели.",
  "items:slayer_hunters_cape:name": "Плащ охотника",
  "items:slayer_hunters_elixir:description": "Приберегается для бывалых истребителей. Ускоряет атаки (-600 мс к интервалу), +12% крит, +20% к урону крита на 30 минут. Держит эффект дольше, чем Боевой отвар.",
  "items:slayer_hunters_elixir:name": "Охотничий эликсир истребителя",
  "items:slayer_vambraces:description": "Наручи, изготовленные из обожжённой шкуры Тлеющего Отродья и закалённой башенной кожи. Каждое убийство на охоте затягивает раны охотника: +4 здоровья за убийство.",
  "items:slayer_vambraces:name": "Наручи истребителя",
  "items:slayer_war_brew:description": "Древняя формула Мастера Истребления. Сильно ускоряет атаки (-750 мс к интервалу), +20% крит, +30% к урону крита на 60 минут. Приберегается для величайших охот.",
  "items:slayer_war_brew:name": "Боевое варево истребителя",
  "items:slayer_ward_capsule:description": "Запечатанный сосуд, содержащий все четыре компонента башенного оберега, сплавленные в единое защитное ядро.",
  "items:slayer_ward_capsule:name": "Капсула оберега истребителя",
  "items:smokeweave_cape:name": "Плащ дымного плетения",
  "items:smugglers_key:name": "Ключ контрабандиста",
  "items:sootscale_greaves:name": "Поножи из сажевой чешуи",
  "items:sorrow_staff:name": "Посох скорби",
  "items:soul_amulet:name": "Амулет души",
  "items:soul_flayer_fang:description": "Изогнутый клык, разящий палёными душами. Редкая добыча со свежевателя душ, ценимая как трофей для Стены Трофеев лагеря.",
  "items:cinderwretch_hide:name": "Шкура Тлеющего Отродья",
  "items:cinderwretch_hide:description": "Прочная шкура, почерневшая от вечно тлеющего сердца, содранная с Тлеющего Отродья в глубинах башни. Компонент для Наручей истребителя.",
  "items:soul_flayer_fang:name": "Клык Свежевателя Душ",
  "items:soul_veil:description": "Мерцающий покров, сотканный из эфирной эссенции и пустотных рун. Отражает атаки бестелесных тварей.",
  "items:soul_veil:name": "Покров души",
  "items:soulfire_banquet:name": "Пир душевного огня",
  "items:soulflayer_amulet:name": "Амулет Свежевателя Душ",
