  "items:void_focus:name": "Пустотный фокус",
  "items:void_herald_shard:description": "Кристаллический осколок вестника пустоты, излучающий холодную энергию пустоты. Компонент для Амулета истребителя.",
  "items:void_herald_shard:name": "Осколок Вестника Пустоты",
  "items:void_rod:name": "Пустотная удочка",
  "items:void_rune:name": "Осколок пустоты",
  "items:void_shroud:description": "Плащ, спрядённый из пустотных нитей, добытых с Охотника Пустоты. Гудит подавленной энергией пустоты.",
  "items:void_shroud:name": "Пустотный саван",
  "items:void_sickle:name": "Серп из пустотной стали",
  "items:void_thread:description": "Прядь застывшей энергии пустоты, вытянутая из пустотного охотника. Заготовка для начертания и рунотворчества.",
  "items:void_thread:name": "Пустотная нить",
