  "items:voidwarden_blade:description": "Двуручный клинок, выкованный из застывшей энергии пустоты. Кромка никогда не тупится.",
  "items:voidwarden_blade:name": "Клинок пустотного стража",
  "items:voidweave_handwraps:description": "Обмотки, прошитые шёлком с пустотными рунами. Заклинания заклинателя бьют быстрее и сильнее.",
  "items:voidweave_handwraps:name": "Обмотки пустотного плетения",
  "items:voidweave_mitre:description": "Прошитая пустотной нитью митра, что гудит уничтожающей мощью. Мысли становятся пустотами.",
  "items:voidweave_mitre:name": "Митра пустотного плетения",
  "items:voidweave_sandals:description": "Сандалии из пустотной нити. Носитель не отбрасывает тени.",
  "items:voidweave_sandals:name": "Сандалии пустотного плетения",
  "items:voidweave_skirt:description": "Подол из сплетённой пустотной нити. Земля под ним словно темнеет.",
  "items:voidweave_skirt:name": "Подол пустотного плетения",
  "items:voidweave_vestment:description": "Облачение, сотканное из нитей с пустотными рунами. Магия течёт сквозь него, как вода сквозь ничто.",
  "items:voidweave_vestment:name": "Облачение пустотного плетения",
