  "items:warbanner_cape:name": "Рваный плащ из боевого знамени",
  "items:warchief_cleaver:description": "Выкован для вождя, что мечтал о целой армии. Он всё ещё помнит, как далеко может донести один удар.",
  "items:warchief_cleaver:name": "Секач военного вождя",
  "items:warchief_fist:description": "Костяшки, выкованные из захваченной стали, всё ещё помятые после смотра войск, который он так и не завершил.",
  "items:warchief_fist:name": "Кулак военного вождя",
