  "items:hollowveil_locket:name": "Медальон Пустой Завесы",
  "items:esthar:name": "Эстар, Буря Костей",
  "items:esthar:description": "Кружащая буря костяных клинков, примотанных к рукояти из окаменевшего костного мозга. Взмахнёшь, и оружие завоет.",
  // Waffen-Drop-Erweiterung 2026-07-23 (Chef-Feedback "zu wenig Waffen-Drops")
  "items:duskfang_ripper:name": "Потрошитель \"Клык Сумерек\"",
  "items:ribcage_hewer:name": "Крушитель Рёбер",
  "items:mossheart_crusher:name": "Крушитель \"Моховое Сердце\"",
  "items:chorus_impaler:name": "Пронзатель Хора",
  "items:sentinel_coreblade:name": "Клинок-Ядро Стража",
  "items:colossus_marrowaxe:name": "Костномозговой Топор Колосса",
  "items:wisp_kindled_bough:name": "Ветвь, Зажжённая Блуждающим Огоньком",
  "items:chitinshell_sparker:name": "Искритель из Хитина",
  "items:barrowsong_crook:name": "Скипетр Кургана-Песнопевца",
  "items:briarbound_conduit:name": "Катализатор, Опутанный Тёрном",
  "items:choirbound_relic:name": "Реликвия, Связанная с Хором",
  "items:voidherald_flightbow:name": "Полётный Лук Вестника Пустоты",
  "items:soulflayer_snapbow:name": "Скорострельный Лук Свежевателя Душ",
  "items:voidhusk_deadeye:name": "Меткий Глаз \"Оболочка Пустоты\"",
  // ── New Haven / Encampment (0.3.0, Task #358): 15 Gebäude-Namen + Flavor ──
  "campBuildings:camp_townhall:name": "Ратуша",
  "campBuildings:camp_townhall:description": "Сперва хижина со столом, позже дом с колоколом: кто его слышит, знает, что в New Haven кто-то принимает решения.",
  "campBuildings:camp_watchtower:name": "Дозорная Башня",
  "campBuildings:camp_watchtower:description": "Пока наверху кто-то стоит на страже, работа внизу не останавливается.",
  "campBuildings:camp_storehouse:name": "Амбар",
  "campBuildings:camp_storehouse:description": "Поднят на каменных сваях, чтобы внутрь не пробрались ни сырость, ни крысы. Восс прислал чертёж и наказ пересчитывать всё дважды.",
  "campBuildings:camp_scrivener_tent:name": "Шатёр Писаря",
  "campBuildings:camp_scrivener_tent:description": "Что записано вечером, не придётся решать утром.",
  "campBuildings:camp_fishing_hut:name": "Хижина Рыбака",
  "campBuildings:camp_fishing_hut:description": "Брод даёт больше, чем переправу, если уметь сидеть достаточно тихо.",
  "campBuildings:camp_sawpit:name": "Пильная Яма",
  "campBuildings:camp_sawpit:description": "Один стоит наверху, другой внизу в опилках; брусья выходят так или иначе.",
  "campBuildings:camp_mine_adit:name": "Штольня",
  "campBuildings:camp_mine_adit:description": "Склон ничего не отдаёт даром, но отдаёт.",
  "campBuildings:camp_seed_garden:name": "Семенной Сад",
  "campBuildings:camp_seed_garden:description": "Эта земля давно не рожала ничего доброго; её заново учат доверять.",
  "campBuildings:camp_fence_tent:name": "Шатёр Скупщика",
  "campBuildings:camp_fence_tent:description": "Никто не спрашивает, откуда товар. В этом и есть ремесло.",
  "campBuildings:camp_workyard:name": "Рабочий Двор",
  "campBuildings:camp_workyard:description": "Верстак к верстаку под одним навесом: каждое ремесло спорится быстрее, когда сосед держит клещи.",
  "campBuildings:camp_smelter:name": "Плавильня",
  "campBuildings:camp_smelter:description": "У огня нет рабочих часов: что вошло, выйдет слитками, смотрят за ним или нет.",
  "campBuildings:camp_smokehouse:name": "Коптильня",
  "campBuildings:camp_smokehouse:description": "Дым — самый терпеливый повар королевства.",
  "campBuildings:camp_trophy_wall:name": "Стена Трофеев",
  "campBuildings:camp_trophy_wall:description": "Бренна платит за головы; стена помнит, что их принесли.",
  "campBuildings:camp_warden_shrine:name": "Святилище Безмолвных",
  "campBuildings:camp_warden_shrine:description": "Ни образа, ни рта, ни руки: лишь поднятый камень и надежда, что кто-то слушает.",
  "campBuildings:camp_trade_post:name": "Торговый Пост",
  "campBuildings:camp_trade_post:description": "Мукс шлёт повозку всякий раз, когда дорога позволяет; цены честные, говорит Мукс.",

