  "items:chiselled_recurve:name": "Выщербленный рекурсивный лук",
  "items:nameless_longbow:name": "Лук Безымянных",
  "items:nameless_longbow:description": "Накладки рукояти — пустые таблички для имён, тетива из выцветшего шнура писца. То, что он сражает, не записывается.",
  "items:crownless_warbow:name": "Боевой лук Некоронованного",
  "items:crownless_warbow:description": "Тяжёлый лук из тёмного божественного железа, плечи усажены обломанными зубцами корон. Дражану никогда не нужно было целиться во что-то мелкое.",
  "items:hollowelm_staff:name": "Посох из полого вяза",
  "items:hollowelm_wand:name": "Жезл из полого вяза",
  "items:mourncedar_scepter:name": "Скипетр из траурного кедра",
