  "items:litany_wand:name": "Жезл литании",
  "items:wreathbound_staff:name": "Посох с венком",
  "items:emptied_shrine_focus:name": "Фокус опустевшего алтаря",
  "items:expunger_chisel:name": "Резец Стирателя",
  "items:expunger_chisel:description": "Слишком длинный железный резец, рукоять обмотана пыльным шнуром писца. Его сделали, чтобы изымать вещи из мира, и он делает это до сих пор.",
  "items:crownless_stave:name": "Посох Некоронованного",
  "items:crownless_stave:description": "Посох из чёрного божественного железа в рост человека, увенчанный разорванной пустой оправой короны. Его огонь однажды взяли взаймы и так и не вернули.",
  "items:mourncedar_log:name": "Бревно траурного кедра",
