  "items:duskfang_ripper:description": "Кривой нож из когтя грифа: лёгкий, быстрый и жестокий в замахе.",
  "items:ribcage_hewer:description": "Боевой топор из коры энта, закалённый в смоле Чернотёрна до железной крепости.",
  "items:mossheart_crusher:description": "Молот из ядра голема, спрессованных камня и корней. Каждый удар падает как рухнувшая стена.",
  "items:chorus_impaler:description": "Могильная пика с древком, обмотанным погребальной тканью. На её острие едет молчание склепа.",
  "items:sentinel_coreblade:description": "Двуручный меч, откованный из пластин ядра павшего стража. Он тихо гудит остатками охранного заряда.",
  "items:colossus_marrowaxe:description": "Гигантское лезвие топора из окаменевшей кости. Рубит в самую крупную цель в комнате.",
  "items:wisp_kindled_bough:description": "Ветвь болотного дерева, на узловатом конце которой всё ещё тлеет пойманный огонь блуждающего огонька.",
  "items:chitinshell_sparker:description": "Жезл с сердцевиной из жучиного хитина. При каждом взмахе по нему пробегают разряды.",
  "items:barrowsong_crook:description": "Погребальный скипетр, отнятый у курганного песнопевца. Он до сих пор холоден на ощупь.",
  "items:briarbound_conduit:description": "Шар-катализатор, оплетённый живым терновником. В нём гудит остаток колдовства ведьмы.",
  "items:choirbound_relic:description": "Посох из святилища полого хора. Он вносит их гул в каждый удар.",
  "items:voidherald_flightbow:description": "Длинный лук с тетивой из жил, тронутых пустотой, взятый из реликвария самого вестника.",
  "items:soulflayer_snapbow:description": "Короткий злой лук из рога свежёванных душ. Его тетива натягивается почти беззвучно.",
  "items:voidhusk_deadeye:description": "Тяжёлый длинный лук, обшитый панцирем пустотной оболочки. Создан для одного смертельного выстрела за раз.",
  "categories:bow_normal:name": "Обычные луки",
