  "quests:daily_ma_kill_roc_20:name": "Небесная охота",
  "quests:daily_ma_kill_roc_20:description": "Сбейте 20 рухов, терроризирующих небо Нагорья.",
  "quests:daily_ma_kill_gravecliff_specter_8:name": "Призраки утёса",
  "quests:daily_ma_kill_gravecliff_specter_8:description": "Изгоните 8 призраков Могильного Утёса, что бродят по мостам Нагорья.",
  "quests:daily_ma_kill_highland_wyvern_6:name": "Дозор у виверн",
  "quests:daily_ma_kill_highland_wyvern_6:description": "Убейте 6 горных виверн, пока они не поднялись в воздух.",
  "quests:daily_ma_kill_idol_warden_15:name": "Прорыв стражи",
  "quests:daily_ma_kill_idol_warden_15:description": "Сломайте строй из 15 стражей идола, охраняющих Святилище Идола.",
  "quests:daily_ma_kill_aether_wraith_10:name": "Очищение от эфира",
  "quests:daily_ma_kill_aether_wraith_10:description": "Уничтожьте 10 эфирных призраков, запертых в Святилище Идола.",
  "quests:daily_ma_kill_scale_skarn_8:name": "Охота на драконью шкуру",
  "quests:daily_ma_kill_scale_skarn_8:description": "Сразите 8 драконошкурых скарнов, обосновавшихся в Святилище Идола.",
  "quests:daily_ma_smelt_godiron_3:name": "Тигель божественного железа",
  "quests:daily_ma_smelt_godiron_3:description": "Выплавьте 3 слитка божественного железа, последнюю ступень лестницы металлов.",
  "quests:daily_ma_cook_witherleek_broth_20:name": "Кухня тайного бульона",
