  // claude:2026-10-18T00:30:00+02:00 — Talentbaum Jagdbuch (1.3.0 Säule 0).
  "talentTrees:slayer:name": "Книга охотника",
  "talentTrees:slayer:description": "Охотничья летопись Бренны. Потраченные здесь очки истребления становятся постоянными улучшениями для всего аккаунта.",
  "talentBranches:slayer.companions:name": "Спутники",
  "talentBranches:slayer.hunt:name": "Охота",
  "talentBranches:slayer.lore:name": "Знание",
  "talentNodes:slayer.tracking:name": "Чтение следов",
  "talentNodes:slayer.tracking:description": "Каждый спутник выпадает на {value} чаще.",
  "talentNodes:slayer.trail:name": "Взятый след",
  "talentNodes:slayer.trail:description": "После {value} от ожидаемого числа попыток без спутника следующий бросок гарантирован.",
  "talentNodes:slayer.collar:name": "Второй ошейник",
  "talentNodes:slayer.collar:description": "Открывает второе место для спутника. Там действует только пассивный эффект.",
  "talentNodes:slayer.pace:name": "Темп охоты",
  "talentNodes:slayer.pace:description": "Выполненные задания приносят на {value} больше очков истребления.",
  "talentNodes:slayer.spoils:name": "Добыча",
  "talentNodes:slayer.spoils:description": "Редкая добыча (1/500 и реже) с монстра твоего задания выпадает на {value} вероятнее.",
  "talentNodes:slayer.lore:name": "Знание охотника",
  "talentNodes:slayer.lore:description": "Ты наносишь на {value} больше урона семействам монстров с полным бестиарием.",
  // claude:2026-10-18T12:00:00+02:00 — Narbenbuch (Prestige „Der Aschesturz“, Welle B2): Baum, Äste, Knoten.
  "talentTrees:prestige:name": "Книга шрамов",
  "talentTrees:prestige:description": "Летопись Стража о каждом Пеплопаде. Шрамы, полученные у Алтаря осколков, становятся здесь постоянными дарами для каждого следующего прохождения.",
  "talentBranches:prestige.legacy:name": "Что остаётся",
  "talentBranches:prestige.haste:name": "Короткий путь",
  "talentBranches:prestige.might:name": "Отмеченный",
  "talentBranches:prestige.crown:name": "Замковый камень",
  "talentNodes:prestige.startingGold:name": "Могильные монеты",
  "talentNodes:prestige.startingGold:description": "Каждое новое прохождение ты начинаешь с {value} золота. Мёртвым дают монеты в дорогу. Ты не мёртв, но монеты не помешают.",
  "talentNodes:prestige.keepTools:name": "Мозоли",
  "talentNodes:prestige.keepTools:description": "Все твои инструменты переживают Пеплопад и ждут в банке. Руки не забывают свой инструмент.",
  "talentNodes:prestige.keepBankStacks:name": "Зарытый сундук",
  "talentNodes:prestige.keepBankStacks:description": "{value} стопок материалов или расходников переживают Пеплопад, до 50 штук в каждой. Что было зарыто, огня не видело.",
  "talentNodes:prestige.keepEquipment:name": "Реликвия",
  "talentNodes:prestige.keepEquipment:description": "Выбранное снаряжение переживает Пеплопад (предметов: {value}), если каждый предмет требует 80 уровня или выше. Вещь, которую пепел не получит.",
  "talentNodes:prestige.earlyXp:name": "Годы ученичества",
  "talentNodes:prestige.earlyXp:description": "На {value} больше опыта навыков ниже 80 уровня. Что однажды выучил, во второй раз учишь быстрее.",
  "talentNodes:prestige.chronicleRecall:name": "Знакомые страницы",
  "talentNodes:prestige.chronicleRecall:description": "Прожитые главы Хроники с 1 по 18 можно завершить одним щелчком, за половину золота и без жетонов и предметов. Хроника не читает тебе дважды главу, которую ты уже прожил.",
  "talentNodes:prestige.masteredXp:name": "Вторая натура",
  "talentNodes:prestige.masteredXp:description": "На {value} больше опыта до 99 уровня в навыках, которые ты уже однажды освоил. Руки всё ещё помнят, куда тянуться.",
  "talentNodes:prestige.dungeonRecall:name": "Старые тропы",
  "talentNodes:prestige.dungeonRecall:description": "Подземелья, зачищенные в прошлом прохождении, сразу открыты для тебя. Врата, которые ты однажды зачистил, тебя узнают.",
  "talentNodes:prestige.maxHp:name": "Рубцовая ткань",
  "talentNodes:prestige.maxHp:description": "На {value} больше максимального здоровья. Рубцовая ткань рвётся не так легко.",
  "talentNodes:prestige.damage:name": "Кулак в шрамах",
  "talentNodes:prestige.damage:description": "Ты наносишь на {value} больше урона. Костяшки, которые однажды уже ломались, больше не ломаются.",
  "talentNodes:prestige.goldFind:name": "Сорочий глаз",
  "talentNodes:prestige.goldFind:description": "На {value} больше золота от действий, боёв, подземелий и заданий, но не от продажи. Ты собираешь то, что принадлежало идолам, как сороки собирают серебро.",
  "talentNodes:prestige.pointsBoost:name": "Глубокий надрез",
  "talentNodes:prestige.pointsBoost:description": "Каждый следующий Пеплопад приносит на {value} больше шрамов. Следующее падение режет глубже и оставляет больше.",
  // claude:2026-10-23T22:55:00+02:00 — Reliktstaub (1.4.0 Bergung)
